+      cache: 'no-store', headers: { 'Idempotency-Key': commandId,
+        ...(context?.apiToken ? { Authorization: `Bearer ${context.apiToken}` } : {}) },
+      ...(context?.signal ? { signal: context.signal } : {}),
+    }).then(raw => {
+      const result = raciOutcomeSchema.safeParse(raw);
