+  return render(<MemoryRouter initialEntries={[`/social/eventos/80${query}`]}>
+    <Routes><Route path="/social/eventos/:eventId" element={<Workspace />} /></Routes>
+  </MemoryRouter>);
+}
+test('ordinary event links preserve the existing overview', async () => {
